// Des: Tests for ru-page-walk: M2 gate end to end on the mock
// Flo: mock + temp db > seed/sitemap > run > assert counts, rows, logs
// I/O: mock responses > pass or fail (no leaks)
// Run: zig build test
// ===================================================================
const std = @import("std"); const walk = @import("ru-page-walk.zig"); const inde = @import("st-page-inde.zig"); const fron = @import("qu-fron-main.zig"); const mock = @import("te-mock-serv.zig"); const sqli = @import("st-stor-sqli.zig"); const vmoc = @import("nt-vend-mock.zig"); const cfgz = @import("cf-conf-load.zig");
const allo = std.testing.allocator;
const Rigg = struct { tmpz: std.testing.TmpDir, srv2: mock.Mock, dirz: []u8, dbzz: sqli.Dbzz, aren: std.heap.ArenaAllocator, wlk2: walk.Walk,
pub fn upzz(self: *Rigg) !void { self.tmpz = std.testing.tmpDir(.{}); self.dirz = try std.fmt.allocPrint(allo, ".zig-cache/tmp/{s}", .{self.tmpz.sub_path}); try self.srv2.sta2(std.testing.io); self.dbzz = try inde.pageOpen(allo, std.testing.io, self.dirz); self.aren = std.heap.ArenaAllocator.init(allo); self.wlk2 = walk.Walk.init(allo, std.testing.io, .{}, &self.dbzz, self.dirz, true); self.wlk2.gapz = 0; self.wlk2.base = 0; }
pub fn down(self: *Rigg) void { self.wlk2.deinit(); self.aren.deinit(); self.dbzz.close(); self.srv2.halt(); allo.free(self.dirz); self.tmpz.cleanup(); }
pub fn url(self: *Rigg, path: []const u8) []const u8 { var buf4: [96]u8 = undefined; return self.aren.allocator().dupe(u8, self.srv2.urlzOfzz(&buf4, path)) catch ""; } };
test "sitemap seeds, robots denies /private with a logged decision, JSON-LD wins over text" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); const addz = try rig3.wlk2.walkSmap(rig3.url("/")); try std.testing.expectEqual(@as(u32, 4), addz); const sum5 = try rig3.wlk2.walkRunz(3); try std.testing.expectEqual(@as(u32, 3), sum5.done); try std.testing.expectEqual(@as(u32, 1), sum5.skip); try std.testing.expect(!sum5.halt and !sum5.incm); try std.testing.expect(try inde.pageGetz(&rig3.dbzz, rig3.aren.allocator(), rig3.url("/private")) == null); const rec2 = (try inde.recoGetz(&rig3.dbzz, rig3.aren.allocator(), rig3.url("/p2"))).?; try std.testing.expectEqualStrings("ldjs", rec2.kind); const rec1 = (try inde.recoGetz(&rig3.dbzz, rig3.aren.allocator(), rig3.url("/p1"))).?; try std.testing.expectEqualStrings("text", rec1.kind); try std.testing.expect(std.mem.indexOf(u8, rec1.body, "Item 1 page text") != null); var stmt = try rig3.dbzz.prep("SELECT count(*) FROM logz WHERE robo LIKE 'deny: /private%';"); defer stmt.fini(); _ = try stmt.step(); try std.testing.expectEqual(@as(i64, 1), stmt.colzIntz(0)); }
test "block page is rejected, retried, then lands in the DLQ; nothing stored" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); _ = try rig3.wlk2.walkSeed(&.{rig3.url("/blockp")}); const sum5 = try rig3.wlk2.walkRunz(null); try std.testing.expectEqual(@as(u32, 0), sum5.done); try std.testing.expectEqual(@as(u32, 3), sum5.blok); try std.testing.expectEqual(@as(i64, 1), sum5.dead); try std.testing.expect(try inde.pageGetz(&rig3.dbzz, rig3.aren.allocator(), rig3.url("/blockp")) == null); const dead = try fron.fronDead(&rig3.dbzz, rig3.aren.allocator()); try std.testing.expectEqualStrings("bloc", dead[0].errz); }
test "poison URLs (non-text, loop) go straight to the DLQ without tripping the breaker" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); _ = try rig3.wlk2.walkSeed(&.{ rig3.url("/img"), rig3.url("/loop"), rig3.url("/p1") }); const sum5 = try rig3.wlk2.walkRunz(null); try std.testing.expectEqual(@as(i64, 2), sum5.dead); try std.testing.expectEqual(@as(u32, 1), sum5.done); try std.testing.expect(!sum5.halt); }
test "breaker trips on a failure spike and halts the run" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); var indx: usize = 0; while (indx < 30) : (indx += 1) { var pbuf: [32]u8 = undefined; _ = try rig3.wlk2.walkSeed(&.{rig3.url(try std.fmt.bufPrint(&pbuf, "/blockp?n={d}", .{indx}))}); } const sum5 = try rig3.wlk2.walkRunz(null); try std.testing.expect(sum5.halt); try std.testing.expect(sum5.seen < 30); try std.testing.expect(try fron.fronCont(&rig3.dbzz, 0) > 0); }
test "flaky host recovers after retries" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); _ = try rig3.wlk2.walkSeed(&.{rig3.url("/flaky")}); const sum5 = try rig3.wlk2.walkRunz(null); try std.testing.expectEqual(@as(u32, 1), sum5.done); try std.testing.expectEqual(@as(u32, 2), sum5.fail); try std.testing.expectEqual(@as(i64, 0), sum5.dead); }
test "short run against a declared total is flagged incomplete" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); _ = try rig3.wlk2.walkSeed(&.{ rig3.url("/p1"), rig3.url("/p2"), rig3.url("/p3") }); const sum5 = try rig3.wlk2.walkRunz(5); try std.testing.expectEqual(@as(u32, 3), sum5.uniq); try std.testing.expect(sum5.incm); }
test "crash resume: a claimed URL is picked up again, never fetched twice into the store" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); _ = try rig3.wlk2.walkSeed(&.{rig3.url("/p1")}); const duez = try fron.fronDuez(&rig3.dbzz, rig3.aren.allocator(), std.math.maxInt(i64), 5); try fron.fronLock(&rig3.dbzz, duez[0].urlz); const sum5 = try rig3.wlk2.walkRunz(null); try std.testing.expectEqual(@as(u32, 1), sum5.done); var stmt = try rig3.dbzz.prep("SELECT count(*) FROM page;"); defer stmt.fini(); _ = try stmt.step(); try std.testing.expectEqual(@as(i64, 1), stmt.colzIntz(0)); }
test "Retry-After holds the host before the retry" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); rig3.wlk2.conf.retr_cont_maxz = 2; _ = try rig3.wlk2.walkSeed(&.{rig3.url("/e503")}); const t0zz = std.Io.Clock.awake.now(std.testing.io).toMilliseconds(); const sum5 = try rig3.wlk2.walkRunz(null); const used = std.Io.Clock.awake.now(std.testing.io).toMilliseconds() - t0zz; try std.testing.expect(used >= 900); try std.testing.expectEqual(@as(i64, 1), sum5.dead); }
test "walker with the ladder: blocked page is rescued by the vendor inside free credits" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); var vmkz = vmoc.Mock.init(allo); defer vmkz.deinit(); vmkz.rul2 = &.{.{ .hasz = "blockp", .minm = .rend }}; rig3.wlk2.conf.vend_free_cred = .{ .deco = 50, .zenr = 50, .brig = 50 }; rig3.wlk2.back = vmkz.bac2(); _ = try rig3.wlk2.walkSeed(&.{ rig3.url("/blockp"), rig3.url("/p1") }); const sum5 = try rig3.wlk2.walkRunz(null); try std.testing.expectEqual(@as(u32, 2), sum5.done); try std.testing.expectEqual(@as(usize, 2), vmkz.cal3.items.len); try std.testing.expect(!sum5.halt); }
test "walker with the ladder: no free credits and no go stops the run instead of burning retries" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); var vmkz = vmoc.Mock.init(allo); defer vmkz.deinit(); rig3.wlk2.back = vmkz.bac2(); _ = try rig3.wlk2.walkSeed(&.{ rig3.url("/blockp"), rig3.url("/blockp?n=2"), rig3.url("/blockp?n=3") }); const sum5 = try rig3.wlk2.walkRunz(null); try std.testing.expect(sum5.halt); try std.testing.expectEqual(@as(usize, 0), vmkz.cal3.items.len); try std.testing.expectEqual(@as(u32, 1), sum5.seen); }
test "walkRevi puts due pages back in the queue" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); _ = try rig3.wlk2.walkSeed(&.{rig3.url("/p1")}); _ = try rig3.wlk2.walkRunz(null); try std.testing.expectEqual(@as(u32, 0), try rig3.wlk2.walkRevi(10)); try rig3.dbzz.exec("UPDATE page SET next=0;"); try std.testing.expectEqual(@as(u32, 1), try rig3.wlk2.walkRevi(10)); const sum5 = try rig3.wlk2.walkRunz(null); try std.testing.expectEqual(@as(u32, 1), sum5.done); }
